     1→/**
     2→ * Bridge Manager — singleton orchestrator for the multi-IM bridge system.
     3→ *
     4→ * Manages adapter lifecycles, routes inbound messages through the
     5→ * conversation engine, and coordinates permission handling.
     6→ *
     7→ * Uses globalThis to survive Next.js HMR in development.
     8→ */
     9→
    10→import type { BridgeStatus, InboundMessage, OutboundMessage, StreamingPreviewState } from './types.js';
    11→import { createAdapter, getRegisteredTypes } from './channel-adapter.js';
    12→import type { BaseChannelAdapter } from './channel-adapter.js';
    13→// Side-effect import: triggers self-registration of all adapter factories
    14→import './adapters/index.js';
    15→import * as router from './channel-router.js';
    16→import * as engine from './conversation-engine.js';
    17→import * as broker from './permission-broker.js';
    18→import { deliver, deliverRendered } from './delivery-layer.js';
    19→import { markdownToTelegramChunks } from './markdown/telegram.js';
    20→import { markdownToDiscordChunks } from './markdown/discord.js';
    21→import { getBridgeContext } from './context.js';
    22→import { escapeHtml } from './adapters/telegram-utils.js';
    23→import {
    24→  validateWorkingDirectory,
    25→  validateSessionId,
    26→  isDangerousInput,
    27→  sanitizeInput,
    28→  validateMode,
    29→} from './security/validators.js';
    30→
    31→const GLOBAL_KEY = '__bridge_manager__';
    32→
    33→// ── Streaming preview helpers ──────────────────────────────────
    34→
    35→/** Generate a non-zero random 31-bit integer for use as draft_id. */
    36→function generateDraftId(): number {
    37→  return (Math.floor(Math.random() * 0x7FFFFFFE) + 1); // 1 .. 2^31-1
    38→}
    39→
    40→interface StreamConfig {
    41→  intervalMs: number;
    42→  minDeltaChars: number;
    43→  maxChars: number;
    44→}
    45→
    46→/** Default stream config per channel type. */
    47→const STREAM_DEFAULTS: Record<string, StreamConfig> = {
    48→  telegram: { intervalMs: 700, minDeltaChars: 20, maxChars: 3900 },
    49→  discord: { intervalMs: 1500, minDeltaChars: 40, maxChars: 1900 },
    50→};
    51→
    52→function getStreamConfig(channelType = 'telegram'): StreamConfig {
    53→  const { store } = getBridgeContext();
    54→  const defaults = STREAM_DEFAULTS[channelType] || STREAM_DEFAULTS.telegram;
    55→  const prefix = `bridge_${channelType}_stream_`;
    56→  const intervalMs = parseInt(store.getSetting(`${prefix}interval_ms`) || '', 10) || defaults.intervalMs;
    57→  const minDeltaChars = parseInt(store.getSetting(`${prefix}min_delta_chars`) || '', 10) || defaults.minDeltaChars;
    58→  const maxChars = parseInt(store.getSetting(`${prefix}max_chars`) || '', 10) || defaults.maxChars;
    59→  return { intervalMs, minDeltaChars, maxChars };
    60→}
    61→
    62→/**
    63→ * Check if a message looks like a numeric permission shortcut (1/2/3) for
    64→ * feishu/qq channels WITH at least one pending permission in that chat.
    65→ *
    66→ * This is used by the adapter loop to route these messages to the inline
    67→ * (non-session-locked) path, avoiding deadlock: the session is blocked
    68→ * waiting for the permission to be resolved, so putting "1" behind the
    69→ * session lock would deadlock.
    70→ */
    71→function isNumericPermissionShortcut(channelType: string, rawText: string, chatId: string): boolean {
    72→  if (channelType !== 'feishu' && channelType !== 'qq') return false;
    73→  const normalized = rawText.normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g, '').trim();
    74→  if (!/^[123]$/.test(normalized)) return false;
    75→  const { store } = getBridgeContext();
    76→  const pending = store.listPendingPermissionLinksByChat(chatId);
    77→  return pending.length > 0; // any pending → route to inline path
    78→}
    79→
    80→/** Fire-and-forget: send a preview draft. Only degrades on permanent failure. */
    81→function flushPreview(
    82→  adapter: BaseChannelAdapter,
    83→  state: StreamingPreviewState,
    84→  config: StreamConfig,
    85→): void {
    86→  if (state.degraded || !adapter.sendPreview) return;
    87→
    88→  const text = state.pendingText.length > config.maxChars
    89→    ? state.pendingText.slice(0, config.maxChars) + '...'
    90→    : state.pendingText;
    91→
    92→  state.lastSentText = text;
    93→  state.lastSentAt = Date.now();
    94→
    95→  adapter.sendPreview(state.chatId, text, state.draftId).then(result => {
    96→    if (result === 'degrade') state.degraded = true;
    97→    // 'skip' — transient failure, next flush will retry naturally
    98→  }).catch(() => {
    99→    // Network error — transient, don't degrade
   100→  });
   101→}
   102→
   103→// ── Channel-aware rendering dispatch ──────────────────────────
   104→
   105→import type { ChannelAddress, SendResult } from './types.js';
   106→
   107→/**
   108→ * Render response text and deliver via the appropriate channel format.
   109→ * Telegram: Markdown → HTML chunks via deliverRendered.
   110→ * Other channels: plain text via deliver (no HTML).
   111→ */
   112→async function deliverResponse(
   113→  adapter: BaseChannelAdapter,
   114→  address: ChannelAddress,
   115→  responseText: string,
   116→  sessionId: string,
   117→  replyToMessageId?: string,
   118→): Promise<SendResult> {
   119→  if (adapter.channelType === 'telegram') {
   120→    const chunks = markdownToTelegramChunks(responseText, 4096);
   121→    if (chunks.length > 0) {
   122→      return deliverRendered(adapter, address, chunks, { sessionId, replyToMessageId });
   123→    }
   124→    return { ok: true };
   125→  }
   126→  if (adapter.channelType === 'discord') {
   127→    // Discord: native markdown, chunk at 2000 chars with fence repair
   128→    const chunks = markdownToDiscordChunks(responseText, 2000);
   129→    for (let i = 0; i < chunks.length; i++) {
   130→      const result = await deliver(adapter, {
   131→        address,
   132→        text: chunks[i].text,
   133→        parseMode: 'Markdown',
   134→        replyToMessageId,
   135→      }, { sessionId });
   136→      if (!result.ok) return result;
   137→    }
   138→    return { ok: true };
   139→  }
   140→  if (adapter.channelType === 'feishu') {
   141→    // Feishu: pass markdown through for adapter to format as post/card
   142→    return deliver(adapter, {
   143→      address,
   144→      text: responseText,
   145→      parseMode: 'Markdown',
   146→      replyToMessageId,
   147→    }, { sessionId });
   148→  }
   149→  // Generic fallback: deliver as plain text (deliver() handles chunking internally)
   150→  return deliver(adapter, {
   151→    address,
   152→    text: responseText,
   153→    parseMode: 'plain',
   154→    replyToMessageId,
   155→  }, { sessionId });
   156→}
   157→
   158→interface AdapterMeta {
   159→  lastMessageAt: string | null;
   160→  lastError: string | null;
   161→}
   162→
   163→interface BridgeManagerState {
   164→  adapters: Map<string, BaseChannelAdapter>;
   165→  adapterMeta: Map<string, AdapterMeta>;
   166→  running: boolean;
   167→  startedAt: string | null;
   168→  loopAborts: Map<string, AbortController>;
   169→  activeTasks: Map<string, AbortController>;
   170→  /** Per-session processing chains for concurrency control */
   171→  sessionLocks: Map<string, Promise<void>>;
   172→  autoStartChecked: boolean;
   173→}
   174→
   175→function getState(): BridgeManagerState {
   176→  const g = globalThis as unknown as Record<string, BridgeManagerState>;
   177→  if (!g[GLOBAL_KEY]) {
   178→    g[GLOBAL_KEY] = {
   179→      adapters: new Map(),
   180→      adapterMeta: new Map(),
   181→      running: false,
   182→      startedAt: null,
   183→      loopAborts: new Map(),
   184→      activeTasks: new Map(),
   185→      sessionLocks: new Map(),
   186→      autoStartChecked: false,
   187→    };
   188→  }
   189→  // Backfill sessionLocks for states created before this field existed
   190→  if (!g[GLOBAL_KEY].sessionLocks) {
   191→    g[GLOBAL_KEY].sessionLocks = new Map();
   192→  }
   193→  return g[GLOBAL_KEY];
   194→}
   195→
   196→/**
   197→ * Process a function with per-session serialization.
   198→ * Different sessions run concurrently; same-session requests are serialized.
   199→ */
   200→function processWithSessionLock(sessionId: string, fn: () => Promise<void>): Promise<void> {
   201→  const state = getState();
   202→  const prev = state.sessionLocks.get(sessionId) || Promise.resolve();
   203→  const current = prev.then(fn, fn);
   204→  state.sessionLocks.set(sessionId, current);
   205→  // Cleanup when the chain completes.
   206→  // Suppress rejection on the cleanup chain — callers handle errors on `current` directly.
   207→  current.finally(() => {
   208→    if (state.sessionLocks.get(sessionId) === current) {
   209→      state.sessionLocks.delete(sessionId);
   210→    }
   211→  }).catch(() => {});
   212→  return current;
   213→}
   214→
   215→/**
   216→ * Start the bridge system.
   217→ * Checks feature flags, registers enabled adapters, starts polling loops.
   218→ */
   219→export async function start(): Promise<void> {
   220→  const state = getState();
   221→  if (state.running) return;
   222→
   223→  const { store, lifecycle } = getBridgeContext();
   224→
   225→  const bridgeEnabled = store.getSetting('remote_bridge_enabled') === 'true';
   226→  if (!bridgeEnabled) {
   227→    console.log('[bridge-manager] Bridge not enabled (remote_bridge_enabled != true)');
   228→    return;
   229→  }
   230→
   231→  // Iterate all registered adapter types and create those that are enabled
   232→  for (const channelType of getRegisteredTypes()) {
   233→    const settingKey = `bridge_${channelType}_enabled`;
   234→    if (store.getSetting(settingKey) !== 'true') continue;
   235→
   236→    const adapter = createAdapter(channelType);
   237→    if (!adapter) continue;
   238→
   239→    const configError = adapter.validateConfig();
   240→    if (!configError) {
   241→      registerAdapter(adapter);
   242→    } else {
   243→      console.warn(`[bridge-manager] ${channelType} adapter not valid:`, configError);
   244→    }
   245→  }
   246→
   247→  // Start all registered adapters, track how many succeeded
   248→  let startedCount = 0;
   249→  for (const [type, adapter] of state.adapters) {
   250→    try {
   251→      await adapter.start();
   252→      console.log(`[bridge-manager] Started adapter: ${type}`);
   253→      startedCount++;
   254→    } catch (err) {
   255→      console.error(`[bridge-manager] Failed to start adapter ${type}:`, err);
   256→    }
   257→  }
   258→
   259→  // Only mark as running if at least one adapter started successfully
   260→  if (startedCount === 0) {
   261→    console.warn('[bridge-manager] No adapters started successfully, bridge not activated');
   262→    state.adapters.clear();
   263→    state.adapterMeta.clear();
   264→    return;
   265→  }
   266→
   267→  // Mark running BEFORE starting consumer loops — runAdapterLoop checks
   268→  // state.running in its while-condition, so it must be true first.
   269→  state.running = true;
   270→  state.startedAt = new Date().toISOString();
   271→
   272→  // Notify host that bridge is starting (e.g., suppress competing polling)
   273→  lifecycle.onBridgeStart?.();
   274→
   275→  // Now start the consumer loops (state.running is already true)
   276→  for (const [, adapter] of state.adapters) {
   277→    if (adapter.isRunning()) {
   278→      runAdapterLoop(adapter);
   279→    }
   280→  }
   281→
   282→  console.log(`[bridge-manager] Bridge started with ${startedCount} adapter(s)`);
   283→}
   284→
   285→/**
   286→ * Stop the bridge system gracefully.
   287→ */
   288→export async function stop(): Promise<void> {
   289→  const state = getState();
   290→  if (!state.running) return;
   291→
   292→  const { lifecycle } = getBridgeContext();
   293→
   294→  state.running = false;
   295→
   296→  // Abort all event loops
   297→  for (const [, abort] of state.loopAborts) {
   298→    abort.abort();
   299→  }
   300→  state.loopAborts.clear();
   301→
   302→  // Stop all adapters
   303→  for (const [type, adapter] of state.adapters) {
   304→    try {
   305→      await adapter.stop();
   306→      console.log(`[bridge-manager] Stopped adapter: ${type}`);
   307→    } catch (err) {
   308→      console.error(`[bridge-manager] Error stopping adapter ${type}:`, err);
   309→    }
   310→  }
   311→
   312→  state.adapters.clear();
   313→  state.adapterMeta.clear();
   314→  state.startedAt = null;
   315→
   316→  // Notify host that bridge stopped
   317→  lifecycle.onBridgeStop?.();
   318→
   319→  console.log('[bridge-manager] Bridge stopped');
   320→}
   321→
   322→/**
   323→ * Lazy auto-start: checks bridge_auto_start setting once and starts if enabled.
   324→ * Called from POST /api/bridge with action 'auto-start' (triggered by Electron on startup).
   325→ */
   326→export function tryAutoStart(): void {
   327→  const state = getState();
   328→  if (state.autoStartChecked) return;
   329→  state.autoStartChecked = true;
   330→
   331→  if (state.running) return;
   332→
   333→  const { store } = getBridgeContext();
   334→  const autoStart = store.getSetting('bridge_auto_start');
   335→  if (autoStart !== 'true') return;
   336→
   337→  start().catch(err => {
   338→    console.error('[bridge-manager] Auto-start failed:', err);
   339→  });
   340→}
   341→
   342→/**
   343→ * Get the current bridge status.
   344→ */
   345→export function getStatus(): BridgeStatus {
   346→  const state = getState();
   347→  return {
   348→    running: state.running,
   349→    startedAt: state.startedAt,
   350→    adapters: Array.from(state.adapters.entries()).map(([type, adapter]) => {
   351→      const meta = state.adapterMeta.get(type);
   352→      return {
   353→        channelType: adapter.channelType,
   354→        running: adapter.isRunning(),
   355→        connectedAt: state.startedAt,
   356→        lastMessageAt: meta?.lastMessageAt ?? null,
   357→        error: meta?.lastError ?? null,
   358→      };
   359→    }),
   360→  };
   361→}
   362→
   363→/**
   364→ * Register a channel adapter.
   365→ */
   366→export function registerAdapter(adapter: BaseChannelAdapter): void {
   367→  const state = getState();
   368→  state.adapters.set(adapter.channelType, adapter);
   369→}
   370→
   371→/**
   372→ * Run the event loop for a single adapter.
   373→ * Messages for different sessions are dispatched concurrently;
   374→ * messages for the same session are serialized via session locks.
   375→ */
   376→function runAdapterLoop(adapter: BaseChannelAdapter): void {
   377→  const state = getState();
   378→  const abort = new AbortController();
   379→  state.loopAborts.set(adapter.channelType, abort);
   380→
   381→  (async () => {
   382→    while (state.running && adapter.isRunning()) {
   383→      try {
   384→        const msg = await adapter.consumeOne();
   385→        if (!msg) continue; // Adapter stopped
   386→
   387→        // Callback queries, commands, and numeric permission shortcuts are
   388→        // lightweight — process inline (outside session lock).
   389→        // Regular messages use per-session locking for concurrency.
   390→        //
   391→        // IMPORTANT: numeric shortcuts (1/2/3) for feishu/qq MUST run outside
   392→        // the session lock. The current session is blocked waiting for the
   393→        // permission to be resolved; if "1" enters the session lock queue it
   394→        // deadlocks (permission waits for "1", "1" waits for lock release).
   395→        if (
   396→          msg.callbackData ||
   397→          msg.text.trim().startsWith('/') ||
   398→          isNumericPermissionShortcut(adapter.channelType, msg.text.trim(), msg.address.chatId)
   399→        ) {
   400→          await handleMessage(adapter, msg);
   401→        } else {
   402→          const binding = router.resolve(msg.address);
   403→          // Fire-and-forget into session lock — loop continues to accept
   404→          // messages for other sessions immediately.
   405→          processWithSessionLock(binding.codepilotSessionId, () =>
   406→            handleMessage(adapter, msg),
   407→          ).catch(err => {
   408→            console.error(`[bridge-manager] Session ${binding.codepilotSessionId.slice(0, 8)} error:`, err);
   409→          });
   410→        }
   411→      } catch (err) {
   412→        if (abort.signal.aborted) break;
   413→        const errMsg = err instanceof Error ? err.message : String(err);
   414→        console.error(`[bridge-manager] Error in ${adapter.channelType} loop:`, err);
   415→        // Track last error per adapter
   416→        const meta = state.adapterMeta.get(adapter.channelType) || { lastMessageAt: null, lastError: null };
   417→        meta.lastError = errMsg;
   418→        state.adapterMeta.set(adapter.channelType, meta);
   419→        // Brief delay to prevent tight error loops
   420→        await new Promise(r => setTimeout(r, 1000));
   421→      }
   422→    }
   423→  })().catch(err => {
   424→    if (!abort.signal.aborted) {
   425→      const errMsg = err instanceof Error ? err.message : String(err);
   426→      console.error(`[bridge-manager] ${adapter.channelType} loop crashed:`, err);
   427→      const meta = state.adapterMeta.get(adapter.channelType) || { lastMessageAt: null, lastError: null };
   428→      meta.lastError = errMsg;
   429→      state.adapterMeta.set(adapter.channelType, meta);
   430→    }
   431→  });
   432→}
   433→
   434→/**
   435→ * Handle a single inbound message.
   436→ */
   437→async function handleMessage(
   438→  adapter: BaseChannelAdapter,
   439→  msg: InboundMessage,
   440→): Promise<void> {
   441→  const { store } = getBridgeContext();
   442→
   443→  // Update lastMessageAt for this adapter
   444→  const adapterState = getState();
   445→  const meta = adapterState.adapterMeta.get(adapter.channelType) || { lastMessageAt: null, lastError: null };
   446→  meta.lastMessageAt = new Date().toISOString();
   447→  adapterState.adapterMeta.set(adapter.channelType, meta);
   448→
   449→  // Acknowledge the update offset after processing completes (or fails).
   450→  // This ensures the adapter only advances its committed offset once the
   451→  // message has been fully handled, preventing message loss on crash.
   452→  const ack = () => {
   453→    if (msg.updateId != null && adapter.acknowledgeUpdate) {
   454→      adapter.acknowledgeUpdate(msg.updateId);
   455→    }
   456→  };
   457→
   458→  // Handle callback queries (permission buttons)
   459→  if (msg.callbackData) {
   460→    const handled = broker.handlePermissionCallback(msg.callbackData, msg.address.chatId, msg.callbackMessageId);
   461→    if (handled) {
   462→      // Send confirmation
   463→      const confirmMsg: OutboundMessage = {
   464→        address: msg.address,
   465→        text: 'Permission response recorded.',
   466→        parseMode: 'plain',
   467→      };
   468→      await deliver(adapter, confirmMsg);
   469→    }
   470→    ack();
   471→    return;
   472→  }
   473→
   474→  const rawText = msg.text.trim();
   475→  const hasAttachments = msg.attachments && msg.attachments.length > 0;
   476→
   477→  // Handle image-only download failures — surface error to user instead of silently dropping
   478→  if (!rawText && !hasAttachments) {
   479→    const rawData = msg.raw as { imageDownloadFailed?: boolean; failedCount?: number } | undefined;
   480→    if (rawData?.imageDownloadFailed) {
   481→      await deliver(adapter, {
   482→        address: msg.address,
   483→        text: `Failed to download ${rawData.failedCount ?? 1} image(s). Please try sending again.`,
   484→        parseMode: 'plain',
   485→        replyToMessageId: msg.messageId,
   486→      });
   487→    }
   488→    ack();
   489→    return;
   490→  }
   491→
   492→  // ── Numeric shortcut for permission replies (feishu/qq only) ──
   493→  // On mobile, typing `/perm allow <uuid>` is painful.
   494→  // If the user sends "1", "2", or "3" and there is exactly one pending
   495→  // permission for this chat, map it: 1→allow, 2→allow_session, 3→deny.
   496→  //
   497→  // Input normalization: mobile keyboards / IM clients may send fullwidth
   498→  // digits (１２３), digits with zero-width joiners, or other Unicode
   499→  // variants. NFKC normalization folds them all to ASCII 1/2/3.
   500→  if (adapter.channelType === 'feishu' || adapter.channelType === 'qq') {
   501→    // eslint-disable-next-line no-control-regex
   502→    const normalized = rawText.normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g, '').trim();
   503→    if (/^[123]$/.test(normalized)) {
   504→      const pendingLinks = store.listPendingPermissionLinksByChat(msg.address.chatId);
   505→      if (pendingLinks.length === 1) {
   506→        const actionMap: Record<string, string> = { '1': 'allow', '2': 'allow_session', '3': 'deny' };
   507→        const action = actionMap[normalized];
   508→        const permId = pendingLinks[0].permissionRequestId;
   509→        const callbackData = `perm:${action}:${permId}`;
   510→        const handled = broker.handlePermissionCallback(callbackData, msg.address.chatId);
   511→        const label = normalized === '1' ? 'Allow' : normalized === '2' ? 'Allow Session' : 'Deny';
   512→        if (handled) {
   513→          await deliver(adapter, {
   514→            address: msg.address,
   515→            text: `${label}: recorded.`,
   516→            parseMode: 'plain',
   517→            replyToMessageId: msg.messageId,
   518→          });
   519→        } else {
   520→          await deliver(adapter, {
   521→            address: msg.address,
   522→            text: `Permission not found or already resolved.`,
   523→            parseMode: 'plain',
   524→            replyToMessageId: msg.messageId,
   525→          });
   526→        }
   527→        ack();
   528→        return;
   529→      }
   530→      if (pendingLinks.length > 1) {
   531→        // Multiple pending permissions — numeric shortcut is ambiguous.
   532→        await deliver(adapter, {
   533→          address: msg.address,
   534→          text: `Multiple pending permissions (${pendingLinks.length}). Please use the full command:\n/perm allow|allow_session|deny <id>`,
   535→          parseMode: 'plain',
   536→          replyToMessageId: msg.messageId,
   537→        });
   538→        ack();
   539→        return;
   540→      }
   541→      // pendingLinks.length === 0: no pending permissions, fall through as normal message
   542→    } else if (rawText !== normalized && /^[123]$/.test(rawText) === false) {
   543→      // Log when normalization changed the text — helps diagnose encoding issues
   544→      const codePoints = [...rawText].map(c => 'U+' + c.codePointAt(0)!.toString(16).toUpperCase().padStart(4, '0'));
   545→      console.log(`[bridge-manager] Shortcut candidate raw codepoints: ${codePoints.join(' ')} → normalized: "${normalized}"`);
   546→    }
   547→  }
   548→
   549→  // Check for IM commands (before sanitization — commands are validated individually)
   550→  if (rawText.startsWith('/')) {
   551→    await handleCommand(adapter, msg, rawText);
   552→    ack();
   553→    return;
   554→  }
   555→
   556→  // Sanitize general message text before routing to conversation engine
   557→  const { text, truncated } = sanitizeInput(rawText);
   558→  if (truncated) {
   559→    console.warn(`[bridge-manager] Input truncated from ${rawText.length} to ${text.length} chars for chat ${msg.address.chatId}`);
   560→    store.insertAuditLog({
   561→      channelType: adapter.channelType,
   562→      chatId: msg.address.chatId,
   563→      direction: 'inbound',
   564→      messageId: msg.messageId,
   565→      summary: `[TRUNCATED] Input truncated from ${rawText.length} chars`,
   566→    });
   567→  }
   568→
   569→  if (!text && !hasAttachments) { ack(); return; }
   570→
   571→  // Regular message — route to conversation engine
   572→  const binding = router.resolve(msg.address);
   573→
   574→  // Notify adapter that message processing is starting (e.g., typing indicator)
   575→  adapter.onMessageStart?.(msg.address.chatId);
   576→
   577→  // Create an AbortController so /stop can cancel this task externally
   578→  const taskAbort = new AbortController();
   579→  const state = getState();
   580→  state.activeTasks.set(binding.codepilotSessionId, taskAbort);
   581→
   582→  // ── Streaming preview setup ──────────────────────────────────
   583→  let previewState: StreamingPreviewState | null = null;
   584→  const caps = adapter.getPreviewCapabilities?.(msg.address.chatId) ?? null;
   585→  if (caps?.supported) {
   586→    previewState = {
   587→      draftId: generateDraftId(),
   588→      chatId: msg.address.chatId,
   589→      lastSentText: '',
   590→      lastSentAt: 0,
   591→      degraded: false,
   592→      throttleTimer: null,
   593→      pendingText: '',
   594→    };
   595→  }
   596→
   597→  const streamCfg = previewState ? getStreamConfig(adapter.channelType) : null;
   598→
   599→  // Build the onPartialText callback (or undefined if preview not supported)
   600→  const onPartialText = (previewState && streamCfg) ? (fullText: string) => {
   601→    const ps = previewState!;
   602→    const cfg = streamCfg!;
   603→    if (ps.degraded) return;
   604→
   605→    // Truncate to maxChars + ellipsis
   606→    ps.pendingText = fullText.length > cfg.maxChars
   607→      ? fullText.slice(0, cfg.maxChars) + '...'
   608→      : fullText;
   609→
   610→    const delta = ps.pendingText.length - ps.lastSentText.length;
   611→    const elapsed = Date.now() - ps.lastSentAt;
   612→
   613→    if (delta < cfg.minDeltaChars && ps.lastSentAt > 0) {
   614→      // Not enough new content — schedule trailing-edge timer if not already set
   615→      if (!ps.throttleTimer) {
   616→        ps.throttleTimer = setTimeout(() => {
   617→          ps.throttleTimer = null;
   618→          if (!ps.degraded) flushPreview(adapter, ps, cfg);
   619→        }, cfg.intervalMs);
   620→      }
   621→      return;
   622→    }
   623→
   624→    if (elapsed < cfg.intervalMs && ps.lastSentAt > 0) {
   625→      // Too soon — schedule trailing-edge timer to ensure latest text is sent
   626→      if (!ps.throttleTimer) {
   627→        ps.throttleTimer = setTimeout(() => {
   628→          ps.throttleTimer = null;
   629→          if (!ps.degraded) flushPreview(adapter, ps, cfg);
   630→        }, cfg.intervalMs - elapsed);
   631→      }
   632→      return;
   633→    }
   634→
   635→    // Clear any pending trailing-edge timer and flush immediately
   636→    if (ps.throttleTimer) {
   637→      clearTimeout(ps.throttleTimer);
   638→      ps.throttleTimer = null;
   639→    }
   640→    flushPreview(adapter, ps, cfg);
   641→  } : undefined;
   642→
   643→  try {
   644→    // Pass permission callback so requests are forwarded to IM immediately
   645→    // during streaming (the stream blocks until permission is resolved).
   646→    // Use text or empty string for image-only messages (prompt is still required by streamClaude)
   647→    const promptText = text || (hasAttachments ? 'Describe this image.' : '');
   648→
   649→    const result = await engine.processMessage(binding, promptText, async (perm) => {
   650→      await broker.forwardPermissionRequest(
   651→        adapter,
   652→        msg.address,
   653→        perm.permissionRequestId,
   654→        perm.toolName,
   655→        perm.toolInput,
   656→        binding.codepilotSessionId,
   657→        perm.suggestions,
   658→        msg.messageId,
   659→      );
   660→    }, taskAbort.signal, hasAttachments ? msg.attachments : undefined, onPartialText);
   661→
   662→    // Send response text — render via channel-appropriate format
   663→    if (result.responseText) {
   664→      await deliverResponse(adapter, msg.address, result.responseText, binding.codepilotSessionId, msg.messageId);
   665→    } else if (result.hasError) {
   666→      const errorResponse: OutboundMessage = {
   667→        address: msg.address,
   668→        text: `<b>Error:</b> ${escapeHtml(result.errorMessage)}`,
   669→        parseMode: 'HTML',
   670→        replyToMessageId: msg.messageId,
   671→      };
   672→      await deliver(adapter, errorResponse);
   673→    }
   674→
   675→    // Persist the actual SDK session ID for future resume.
   676→    // If the result has an error and no session ID was captured, clear the
   677→    // stale ID so the next message starts fresh instead of retrying a broken resume.
   678→    if (binding.id) {
   679→      try {
   680→        const update = computeSdkSessionUpdate(result.sdkSessionId, result.hasError);
   681→        if (update !== null) {
   682→          store.updateChannelBinding(binding.id, { sdkSessionId: update });
   683→        }
   684→      } catch { /* best effort */ }
   685→    }
   686→  } finally {
   687→    // Clean up preview state
   688→    if (previewState) {
   689→      if (previewState.throttleTimer) {
   690→        clearTimeout(previewState.throttleTimer);
   691→        previewState.throttleTimer = null;
   692→      }
   693→      adapter.endPreview?.(msg.address.chatId, previewState.draftId);
   694→    }
   695→
   696→    state.activeTasks.delete(binding.codepilotSessionId);
   697→    // Notify adapter that message processing ended
   698→    adapter.onMessageEnd?.(msg.address.chatId);
   699→    // Commit the offset only after full processing (success or failure)
   700→    ack();
   701→  }
   702→}
   703→
   704→/**
   705→ * Handle IM slash commands.
   706→ */
   707→async function handleCommand(
   708→  adapter: BaseChannelAdapter,
   709→  msg: InboundMessage,
   710→  text: string,
   711→): Promise<void> {
   712→  const { store } = getBridgeContext();
   713→
   714→  // Extract command and args (handle /command@botname format)
   715→  const parts = text.split(/\s+/);
   716→  const command = parts[0].split('@')[0].toLowerCase();
   717→  const args = parts.slice(1).join(' ').trim();
   718→
   719→  // Run dangerous-input detection on the full command text
   720→  const dangerCheck = isDangerousInput(text);
   721→  if (dangerCheck.dangerous) {
   722→    store.insertAuditLog({
   723→      channelType: adapter.channelType,
   724→      chatId: msg.address.chatId,
   725→      direction: 'inbound',
   726→      messageId: msg.messageId,
   727→      summary: `[BLOCKED] Dangerous input detected: ${dangerCheck.reason}`,
   728→    });
   729→    console.warn(`[bridge-manager] Blocked dangerous command input from chat ${msg.address.chatId}: ${dangerCheck.reason}`);
   730→    await deliver(adapter, {
   731→      address: msg.address,
   732→      text: `Command rejected: invalid input detected.`,
   733→      parseMode: 'plain',
   734→      replyToMessageId: msg.messageId,
   735→    });
   736→    return;
   737→  }
   738→
   739→  let response = '';
   740→
   741→  switch (command) {
   742→    case '/start':
   743→      response = [
   744→        '<b>CodePilot Bridge</b>',
   745→        '',
   746→        'Send any message to interact with Claude.',
   747→        '',
   748→        '<b>Commands:</b>',
   749→        '/new [path] - Start new session',
   750→        '/bind &lt;session_id&gt; - Bind to existing session',
   751→        '/cwd /path - Change working directory',
   752→        '/mode plan|code|ask - Change mode',
   753→        '/status - Show current status',
   754→        '/sessions - List recent sessions',
   755→        '/stop - Stop current session',
   756→        '/perm allow|allow_session|deny &lt;id&gt; - Respond to permission',
   757→        '/help - Show this help',
   758→      ].join('\n');
   759→      break;
   760→
   761→    case '/new': {
   762→      let workDir: string | undefined;
   763→      if (args) {
   764→        const validated = validateWorkingDirectory(args);
   765→        if (!validated) {
   766→          response = 'Invalid path. Must be an absolute path without traversal sequences.';
   767→          break;
   768→        }
   769→        workDir = validated;
   770→      }
   771→      const binding = router.createBinding(msg.address, workDir);
   772→      response = `New session created.\nSession: <code>${binding.codepilotSessionId.slice(0, 8)}...</code>\nCWD: <code>${escapeHtml(binding.workingDirectory || '~')}</code>`;
   773→      break;
   774→    }
   775→
   776→    case '/bind': {
   777→      if (!args) {
   778→        response = 'Usage: /bind &lt;session_id&gt;';
   779→        break;
   780→      }
   781→      if (!validateSessionId(args)) {
   782→        response = 'Invalid session ID format. Expected a 32-64 character hex/UUID string.';
   783→        break;
   784→      }
   785→      const binding = router.bindToSession(msg.address, args);
   786→      if (binding) {
   787→        response = `Bound to session <code>${args.slice(0, 8)}...</code>`;
   788→      } else {
   789→        response = 'Session not found.';
   790→      }
   791→      break;
   792→    }
   793→
   794→    case '/cwd': {
   795→      if (!args) {
   796→        response = 'Usage: /cwd /path/to/directory';
   797→        break;
   798→      }
   799→      const validatedPath = validateWorkingDirectory(args);
   800→      if (!validatedPath) {
   801→        response = 'Invalid path. Must be an absolute path without traversal sequences or special characters.';
   802→        break;
   803→      }
   804→      const binding = router.resolve(msg.address);
   805→      router.updateBinding(binding.id, { workingDirectory: validatedPath });
   806→      response = `Working directory set to <code>${escapeHtml(validatedPath)}</code>`;
   807→      break;
   808→    }
   809→
   810→    case '/mode': {
   811→      if (!validateMode(args)) {
   812→        response = 'Usage: /mode plan|code|ask';
   813→        break;
   814→      }
   815→      const binding = router.resolve(msg.address);
   816→      router.updateBinding(binding.id, { mode: args });
   817→      response = `Mode set to <b>${args}</b>`;
   818→      break;
   819→    }
   820→
   821→    case '/status': {
   822→      const binding = router.resolve(msg.address);
   823→      response = [
   824→        '<b>Bridge Status</b>',
   825→        '',
   826→        `Session: <code>${binding.codepilotSessionId.slice(0, 8)}...</code>`,
   827→        `CWD: <code>${escapeHtml(binding.workingDirectory || '~')}</code>`,
   828→        `Mode: <b>${binding.mode}</b>`,
   829→        `Model: <code>${binding.model || 'default'}</code>`,
   830→      ].join('\n');
   831→      break;
   832→    }
   833→
   834→    case '/sessions': {
   835→      const bindings = router.listBindings(adapter.channelType);
   836→      if (bindings.length === 0) {
   837→        response = 'No sessions found.';
   838→      } else {
   839→        const lines = ['<b>Sessions:</b>', ''];
   840→        for (const b of bindings.slice(0, 10)) {
   841→          const active = b.active ? 'active' : 'inactive';
   842→          lines.push(`<code>${b.codepilotSessionId.slice(0, 8)}...</code> [${active}] ${escapeHtml(b.workingDirectory || '~')}`);
   843→        }
   844→        response = lines.join('\n');
   845→      }
   846→      break;
   847→    }
   848→
   849→    case '/stop': {
   850→      const binding = router.resolve(msg.address);
   851→      const st = getState();
   852→      const taskAbort = st.activeTasks.get(binding.codepilotSessionId);
   853→      if (taskAbort) {
   854→        taskAbort.abort();
   855→        st.activeTasks.delete(binding.codepilotSessionId);
   856→        response = 'Stopping current task...';
   857→      } else {
   858→        response = 'No task is currently running.';
   859→      }
   860→      break;
   861→    }
   862→
   863→    case '/perm': {
   864→      // Text-based permission approval fallback (for channels without inline buttons)
   865→      // Usage: /perm allow <id> | /perm allow_session <id> | /perm deny <id>
   866→      const permParts = args.split(/\s+/);
   867→      const permAction = permParts[0];
   868→      const permId = permParts.slice(1).join(' ');
   869→      if (!permAction || !permId || !['allow', 'allow_session', 'deny'].includes(permAction)) {
   870→        response = 'Usage: /perm allow|allow_session|deny &lt;permission_id&gt;';
   871→        break;
   872→      }
   873→      const callbackData = `perm:${permAction}:${permId}`;
   874→      const handled = broker.handlePermissionCallback(callbackData, msg.address.chatId);
   875→      if (handled) {
   876→        response = `Permission ${permAction}: recorded.`;
   877→      } else {
   878→        response = `Permission not found or already resolved.`;
   879→      }
   880→      break;
   881→    }
   882→
   883→    case '/help':
   884→      response = [
   885→        '<b>CodePilot Bridge Commands</b>',
   886→        '',
   887→        '/new [path] - Start new session',
   888→        '/bind &lt;session_id&gt; - Bind to existing session',
   889→        '/cwd /path - Change working directory',
   890→        '/mode plan|code|ask - Change mode',
   891→        '/status - Show current status',
   892→        '/sessions - List recent sessions',
   893→        '/stop - Stop current session',
   894→        '/perm allow|allow_session|deny &lt;id&gt; - Respond to permission request',
   895→        '1/2/3 - Quick permission reply (Feishu/QQ, single pending)',
   896→        '/help - Show this help',
   897→      ].join('\n');
   898→      break;
   899→
   900→    default:
   901→      response = `Unknown command: ${escapeHtml(command)}\nType /help for available commands.`;
   902→  }
   903→
   904→  if (response) {
   905→    await deliver(adapter, {
   906→      address: msg.address,
   907→      text: response,
   908→      parseMode: 'HTML',
   909→      replyToMessageId: msg.messageId,
   910→    });
   911→  }
   912→}
   913→
   914→// ── SDK Session Update Logic ─────────────────────────────────
   915→
   916→/**
   917→ * Compute the sdkSessionId value to persist after a conversation result.
   918→ * Returns the new value to write, or null if no update is needed.
   919→ *
   920→ * Rules:
   921→ * - If result has sdkSessionId AND no error → save the new ID
   922→ * - If result has error (regardless of sdkSessionId) → clear to empty string
   923→ * - Otherwise → no update needed
   924→ */
   925→export function computeSdkSessionUpdate(
   926→  sdkSessionId: string | null | undefined,
   927→  hasError: boolean,
   928→): string | null {
   929→  if (sdkSessionId && !hasError) {
   930→    return sdkSessionId;
   931→  }
   932→  if (hasError) {
   933→    return '';
   934→  }
   935→  return null;
   936→}
   937→
   938→// ── Test-only export ─────────────────────────────────────────
   939→// Exposed so integration tests can exercise handleMessage directly
   940→// without wiring up the full adapter loop.
   941→/** @internal */
   942→export const _testOnly = { handleMessage };
   943→

